export function getActiveVersion(
  data: GlobalPluginData,
  pathname: string,
): GlobalVersion | undefined {
  // Sort versions by path length (descending), so that we always match the
  // most specific version path first.
  // This is important for paths like "/" or "/docs" that would otherwise
  // match the path of other versions (see https://github.com/facebook/docusaurus/issues/10309)
  const orderedVersionsMetadata = [...data.versions].sort(
    (version1, version2) => version2.path.length - version1.path.length,
  );
  return orderedVersionsMetadata.find(
    (version) =>
      !!matchPath(pathname, {
        path: version.path,
        exact: false,
        strict: false,
      }),
  );
}

